let patternSearch='',patternGroup='all',drillIndex=0,drillChoice=null,traceIndex=0;
const drills=[
{prompt:'Count contiguous segments of a signed integer array whose sum is exactly K.',answer:1,options:[5,1,10],why:'Signed values prevent the ordinary sum-window repair rule. Prefix differences turn equality into frequency lookups; multiplicity matters.'},
{prompt:'Find the minimum daily capacity to ship positive weights in order within D days.',answer:11,options:[11,8,24],why:'Capacity feasibility is monotone. A greedy scan counts required days; binary search finds the first feasible capacity.'},
{prompt:'Return the maximum value in every block of exactly k consecutive numbers.',answer:16,options:[4,12,16],why:'A maximum cannot remove its outgoing contribution by subtraction. A monotonic deque discards dominated candidates and expires old indices.'},
{prompt:'Find a shortest grid route when you may remove up to k obstacles, with unit move costs.',answer:18,options:[18,20,21],why:'Use BFS over (cell, remaining removals). Cell alone is not enough state. Nonuniform edge costs would change the frontier algorithm.'},
{prompt:'Select a maximum-value compatible subset of weighted time intervals.',answer:23,options:[30,23,8],why:'Use take/skip DP with binary-searched compatible predecessors. Earliest finish is correct for maximum count, not arbitrary values.'},
{prompt:'Queries ask whether two vertices connect using edges below a threshold; all queries are known in advance.',answer:21,options:[21,19,6],why:'Sort queries and edges by threshold. DSU incrementally represents connectivity as eligible edges are added.'},
{prompt:'Count unordered ways to make an amount with unlimited copies of distinct positive denominations.',answer:25,options:[24,25,26],why:'Use unbounded combination DP: denominations outside, ascending amounts inside. Reversing loop order can count ordered sequences instead.'},
{prompt:'A dictionary must answer whether any word starts with a supplied prefix.',answer:29,options:[29,32,0],why:'A trie represents shared prefixes directly. A hash set answers full-key membership but not arbitrary prefix existence without additional indexing.'}
];
function patternQuestions(p){return p.ids.map(id=>questions.find(q=>q.id===id)).filter(Boolean)}
function patternCard(p){const all=patternQuestions(p),done=all.filter(complete).length;return `<article class="card"><a class="stretched" href="#pattern/${p.id}"><div class="card-top"><span class="phase-icon">${String(p.id+1).padStart(2,'0')}</span><span class="tag">${esc(p.group)}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.cue)}</p><div class="bar"><i style="width:${Math.round(done/all.length*100)}%"></i></div><div class="card-bottom"><span>${done}/${all.length} ladder questions independent</span><span>Explore →</span></div></a></article>`}
function patternsPage(){return heading('A REUSABLE WAY TO THINK','Pattern atlas','Recognize the structure. Prove the invariant. Adapt the technique.')+`<div class="mastery-banner"><div><strong>${COURSE.patterns.length} patterns. One connected practice library.</strong><p>Each pattern has recognition cues, a template, pitfalls, a follow-up, and an ordered practice ladder.</p></div><a class="btn" href="#pattern-drill">Try recognition drills →</a></div><div class="controls"><a class="btn light" href="patterns-guide.md" download>Download pattern handbook ↓</a><a class="btn light" href="#pattern/0">Start with the fundamentals →</a><a class="btn light" href="#pattern-trace">Step through two pointers →</a></div><div class="toolbar"><input id="pattern-search" aria-label="Search patterns" placeholder="Search a pattern, signal, or problem…" value="${esc(patternSearch)}"><select id="pattern-group" aria-label="Pattern family"><option value="all">All families</option>${[...new Set(COURSE.patterns.map(p=>p.group))].map(g=>`<option ${g===patternGroup?'selected':''}>${esc(g)}</option>`).join('')}</select></div><div id="pattern-cards"></div><p class="note">Inspired by the pattern-based learning approach of <a href="https://algomaster.io/learn/dsa/course-introduction" target="_blank" rel="noopener">AlgoMaster ↗</a>. This catalog, explanations, drills, and mappings are original and independent. Patterns overlap; this covers the core and specialist families in our roadmap, not every possible algorithm or guaranteed company question.</p>`}
function patternResults(){const list=COURSE.patterns.filter(p=>(patternGroup==='all'||p.group===patternGroup)&&(p.title+' '+p.cue+' '+p.group+' '+patternQuestions(p).map(q=>q.title+' '+q.id).join(' ')).toLowerCase().includes(patternSearch.toLowerCase()));$('#pattern-cards').innerHTML=`<p class="note">${list.length} patterns · core patterns first; specialist extensions follow</p><div class="grid">${list.map(patternCard).join('')}</div>${list.length?'':'<div class="empty">No matching patterns. Try another term or family.</div>'}`}
function patternPage(id){const p=COURSE.patterns.find(p=>p.id===Number(id));if(!p)return '<p>Pattern not found. <a href="#patterns">Return to atlas.</a></p>';return heading(esc(p.group),esc(p.title),'Learn the rule, then test when it stops applying.')+`<div class="controls"><a class="btn light" href="#patterns">← Pattern atlas</a><a class="btn light" href="#phase/${p.phase}">Foundation phase ${p.phase} →</a>${p.deep!==null?`<a class="btn light" href="#deep/${p.deep}">Related deep dive →</a>`:''}<button class="btn" onclick="practicePattern(${p.id})">Practice this pattern →</button></div><div class="pattern-layout"><article class="reader"><h3>01 · Recognition cues</h3><p>${esc(p.cue)}</p><h3>02 · Why it works</h3><p>${esc(p.invariant)}</p><h3>03 · Worked example</h3><p>${esc(p.example)}</p>${p.id===2?'<a class="btn light" href="#pattern-trace">Walk through the pointer moves →</a>':''}<h3>04 · Template</h3><p class="note">Python-style reference. Some templates are schematic and require helpers, imports, or problem-specific base cases; adapt and test them in your editor.</p><pre><code>${esc(p.code)}</code></pre><h3>05 · Complexity</h3><p>${esc(p.cost)}</p><h3>06 · When it fails</h3><p>${esc(p.trap)}</p><h3>07 · Interview follow-up</h3><p>${esc(p.followup)}</p><h3>08 · Pattern checkpoint</h3><ul><li>Explain the recognition cue and invariant without notes.</li><li>Implement one ladder problem independently and test boundaries.</li><li>Give a counterexample to a wrong application of this pattern.</li><li>Attempt the follow-up with changed constraints.</li></ul></article><section><div class="panel"><div class="eyebrow">PRACTICE LADDER</div><h3>Learn → apply → stretch</h3><p class="note">Suggested sequence, not platform difficulty. Status is shared with the question bank.</p>${patternQuestions(p).map((q,i)=>`<div class="ladder-row"><div class="note">STEP ${i+1} · #${q.id}</div><a target="_blank" rel="noopener" href="https://leetcode.com/problemset/?search=${encodeURIComponent(q.title)}">${esc(q.title)} ↗</a><select data-pattern-q="${q.id}" aria-label="Progress for ${esc(q.title)}">${states.map(s=>`<option ${status(q)===s?'selected':''}>${s}</option>`).join('')}</select></div>`).join('')}</div><div class="panel" style="margin-top:16px"><label for="pattern-confidence"><strong>Pattern confidence</strong></label><select id="pattern-confidence" data-pattern-id="${p.id}" style="display:block;width:100%;margin-top:12px">${['New','Can recognize','Can explain','Can transfer'].map(s=>`<option ${(saved.notes[3000+p.id]||'New')===s?'selected':''}>${s}</option>`).join('')}</select><p class="note">Self-assessment, separate from question completion.</p><textarea data-mastery-note="${3100+p.id}" aria-label="Pattern notes" placeholder="My recognition cues, invariant, counterexample, and follow-up result…">${esc(saved.notes[3100+p.id]||'')}</textarea></div></section></div><div class="controls">${p.id>0?`<a class="btn light" href="#pattern/${p.id-1}">← Previous pattern</a>`:''}${p.id<COURSE.patterns.length-1?`<a class="btn" href="#pattern/${p.id+1}">Next pattern →</a>`:''}</div>`}
function practicePattern(id){filter={search:'',phase:'all',tier:'all',status:'all',pattern:String(id)};location.hash='questions'}
function patternDrill(){const d=drills[drillIndex],answered=drillChoice!==null;return heading('RECOGNITION PRACTICE','Which pattern fits—and why?','Choose the technique before looking at code. Then explain the assumption it relies on.')+`<div class="reader"><div class="eyebrow">SCENARIO ${drillIndex+1} / ${drills.length}</div><h3>${esc(d.prompt)}</h3><div class="drill-options">${d.options.map(id=>`<button class="btn light ${drillChoice===id?'chosen':''}" onclick="choosePatternDrill(${id})" ${answered?'disabled':''}>${esc(COURSE.patterns[id].title)}</button>`).join('')}</div>${answered?`<div class="panel callout" role="status"><strong>${drillChoice===d.answer?'Correct choice':'A better fit: '+esc(COURSE.patterns[d.answer].title)}</strong><p>${esc(d.why)}</p><a href="#pattern/${d.answer}">Study this pattern →</a></div><h4>Make it harder</h4><p>${esc(COURSE.patterns[d.answer].followup)}</p>`:'<p class="note">The best answer depends on the stated constraints. Topic names alone are not a proof.</p>'}<div class="controls"><button class="btn light" onclick="movePatternDrill(-1)" ${drillIndex===0?'disabled':''}>← Previous</button><button class="btn" onclick="movePatternDrill(1)">${drillIndex===drills.length-1?'Restart drills':'Next scenario →'}</button></div></div>`}
function choosePatternDrill(id){if(drillChoice!==null)return;drillChoice=id;render()}
function movePatternDrill(delta){drillIndex=(drillIndex+delta+drills.length)%drills.length;drillChoice=null;render()}
const pointerTrace=[{l:0,r:3,action:'1 + 8 = 9, too large. With right=3, every larger left is also too large; discard the right endpoint.'},{l:0,r:2,action:'1 + 4 = 5, too small. Every earlier right with left=0 is no larger; discard the left endpoint.'},{l:1,r:2,action:'3 + 4 = 7. A valid pair is found at indices 1 and 2.'}];
function patternTrace(){const t=pointerTrace[traceIndex];return heading('INTERACTIVE WALKTHROUGH','Watch the invariant at work','Sorted pair search · [1, 3, 4, 8] · target = 7')+`<div class="reader"><p>At each step, discard an endpoint only when sorted order proves it cannot belong to a solution in the remaining range.</p><div class="trace-array">${[1,3,4,8].map((v,i)=>`<div class="trace-cell ${i===t.l||i===t.r?'selected':''} ${i<t.l||i>t.r?'discarded':''}"><span class="note">index ${i}</span><strong>${v}</strong><small>${i===t.l?'LEFT':i===t.r?'RIGHT':' '}</small></div>`).join('')}</div><p class="trace-explanation" aria-live="polite">${esc(t.action)}</p><div class="controls"><button class="btn light" onclick="traceIndex--;render()" ${traceIndex===0?'disabled':''}>← Back</button><button class="btn" onclick="traceIndex++;render()" ${traceIndex===2?'disabled':''}>Next step →</button><button class="btn light" onclick="traceIndex=0;render()">Reset</button></div><p class="note">Step ${traceIndex+1} of 3. Try an unsorted array to see why the discard proof fails.</p><a href="#pattern/2">Return to the two-pointer pattern →</a></div>`}
function patternBind(){if($('#pattern-search')){patternResults();$('#pattern-search').oninput=e=>{patternSearch=e.target.value;patternResults()};$('#pattern-group').onchange=e=>{patternGroup=e.target.value;patternResults()}}if($('#pattern-confidence'))$('#pattern-confidence').onchange=e=>{saved.notes[3000+Number(e.target.dataset.patternId)]=e.target.value;persist()};document.querySelectorAll('[data-pattern-q]').forEach(el=>el.onchange=()=>{saved.q[el.dataset.patternQ]={status:el.value,updated:Date.now(),due:Date.now()+({'New':0,'Learning':1,'Independent':3,'Retained':14,'Transfer':30}[el.value]*86400000)};persist();toast('Question progress updated across your workspace.')});if($('#pattern-filter'))$('#pattern-filter').onchange=e=>{filter.pattern=e.target.value;results()}}
